184	/** @brief 一段文字的量：advance（排版宽）+ 首字墨迹偏移 + 墨迹宽。 */
185	typedef struct {
186	    int adv;
187	    int ink_x0;
188	    int ink_w;
189	} sb_text_metrics_t;
190	
191	/**
192	 * @brief 12 px 状态栏字体里实际用到的 13 个字形的**渲染墨迹**列（相对笔位）。
193	 *
194	 * @details `lv_font_get_glyph_dsc()` 给的 `box_w` 是字模框，不等于屏上墨迹：
195	 *          这份 2 bpp 字模把多行像素连续打包（`stride == 0`），且框的左/右
196	 *          各可能有全空列（如 `%` 框 12 列，只有第 1..10 列有墨）。设计又要求
197	 *          **按墨迹**对齐（时间 x0=12、电量 x1=216、间隙 7），所以按实测表算。
198	 *          数值来自 /tmp 下的字模探针（逐像素解包 `helm_ui_12` 的 2 bpp 流，
199	 *          与模拟器截图逐列核对）；字符串只可能是 `0-9 : % -`。
200	 *          ⚠ 换状态栏字体或字号后必须重测本表。
201	 */
202	typedef struct {
203	    char ch;
204	    int8_t ink0;
205	    int8_t ink1;
206	} sb_glyph_ink_t;
207	
208	static const sb_glyph_ink_t s_glyph_ink[] = {
209	    { '0', 0, 6 }, { '1', 1, 3 }, { '2', 1, 6 }, { '3', 1, 6 },
210	    { '4', 0, 7 }, { '5', 1, 6 }, { '6', 1, 6 }, { '7', 1, 6 },
211	    { '8', 1, 6 }, { '9', 1, 6 }, { ':', 1, 1 }, { '%', 1, 10 },
212	    { '-', 1, 6 },
213	};
214	
215	static bool sb_glyph_ink_of(char ch, int * ink0, int * ink1)
216	{
217	    for (size_t i = 0; i < sizeof(s_glyph_ink) / sizeof(s_glyph_ink[0]); i++) {
218	        if (s_glyph_ink[i].ch == ch) {
219	            *ink0 = s_glyph_ink[i].ink0;
220	            *ink1 = s_glyph_ink[i].ink1;
221	            return true;
222	        }
223	    }
224	    return false;
225	}
226	
227	/**
228	 * @brief 量时间/电量这类纯 ASCII 短串的 advance 与**墨迹**边界。
229	 *
230	 * @details 设计按墨迹对齐（x0=12、x1=216、间隙 7），而 12 px 点阵的
231	 *          side bearing 与空列都不为 0，所以不能拿 advance 当墨迹用。
232	 *          字符串只可能是 `0-9 : % -`，按字节迭代 + 上面的实测表即可。
233	 */
234	static void sb_text_measure(const char * txt, sb_text_metrics_t * m)
235	{
236	    lv_point_t sz;
237	    int pen = 0;
238	    int minx = 0x7FFF;
239	    int maxx = -0x8000;
240	
241	    lv_text_get_size(&sz, txt, s_font, 0, 0, LV_COORD_MAX, LV_TEXT_FLAG_NONE);
242	    m->adv = (int)sz.x;
243	
244	    for (const char * p = txt; *p != '\0'; p++) {
245	        const uint32_t cp = (uint8_t)*p;
246	        int ink0;
247	        int ink1;
248	
249	        if (sb_glyph_ink_of((char)cp, &ink0, &ink1)) {
250	            ink0 += pen;
251	            ink1 += pen;
252	        } else {
253	            ink0 = pen;
254	            ink1 = pen + (int)lv_font_get_glyph_width(s_font, cp, 0) - 1;
255	        }
256	
257	        if (ink0 < minx) {
258	            minx = ink0;
259	        }
260	        if (ink1 > maxx) {
261	            maxx = ink1;
262	        }
263	        pen += (int)lv_font_get_glyph_width(s_font, cp, 0);
264	    }
265	
266	    if (maxx < minx) {
267	        m->ink_x0 = 0;
268	        m->ink_w = 0;
269	    } else {
270	        m->ink_x0 = minx;
271	        m->ink_w = maxx - minx + 1;
272	    }
273	}
