291	static uint32_t sb_pal_signature(const struct helm_pal_t * pal)
292	{
293	    if (pal == NULL) {
294	        return 0;
295	    }
296	
297	    /* 只关心顶栏用到的几支：任一支变了就重上色。 */
298	    return pal->paper ^ (pal->hair << 1) ^ (pal->ink << 2) ^
299	           (pal->track << 3) ^ (pal->gps_dead << 4) ^ (pal->ban_nav << 5);
300	}
