342	/**
343	 * @brief 上一次色 + 显隐（幂等）。
344	 *
345	 * @param tone    本拍语义色；SB_TONE_HIDE 表示数据层就不显示。
346	 * @param shown   布局层是否保留（碰撞隐藏时为 false）。
347	 * @param dot_on  连接点是否实心（仅 GPS/BLE 有连接点）。
348	 */
349	static void sb_slot_apply(int k, sb_tone_t tone, bool shown, bool dot_on)
350	{
351	    sb_slot_t * s = &s_slot[k];
352	
353	    if (s->ico == NULL) {
354	        return;
355	    }
356	
357	    if (!shown || tone == SB_TONE_HIDE) {
358	        if (s->vis_last || !lv_obj_has_flag(s->ico, LV_OBJ_FLAG_HIDDEN)) {
359	            sb_hide(s->ico);
360	            s->vis_last = false;
361	        }
362	        if (s->dot != NULL &&
363	            (s->dot_last != 0 ||
364	             !lv_obj_has_flag(s->dot, LV_OBJ_FLAG_HIDDEN))) {
365	            sb_hide(s->dot);
366	            s->dot_last = 0;
367	        }
368	        s->tone_last = SB_TONE_HIDE;
369	        return;
370	    }
371	
372	    if (!s->vis_last) {
373	        sb_show(s->ico);
374	        s->vis_last = true;
375	        s->tone_last = SB_TONE_NONE;   /* 重新取色 */
376	    }
377	
378	    {
379	        bool tone_changed = (s->tone_last != (uint8_t)tone);
380	
381	        if (tone_changed) {
382	            lv_obj_set_style_text_color(s->ico, sb_tone_color(tone), 0);
383	            s->tone_last = (uint8_t)tone;
384	        }
385	
386	        if (s->dot != NULL) {
387	            const uint8_t want = dot_on ? 1u : 2u;
388	
389	            if (want != s->dot_last || tone_changed) {
390	                lv_color_t c = sb_tone_color(tone);
391	
392	                if (want == 1u) {
393	                    lv_obj_set_style_bg_color(s->dot, c, 0);
394	                    lv_obj_set_style_bg_opa(s->dot, LV_OPA_COVER, 0);
395	                    lv_obj_set_style_border_width(s->dot, 0, 0);
396	                } else {
397	                    lv_obj_set_style_bg_opa(s->dot, LV_OPA_TRANSP, 0);
398	                    lv_obj_set_style_border_width(s->dot, 1, 0);
399	                    lv_obj_set_style_border_color(s->dot, c, 0);
400	                    lv_obj_set_style_border_opa(s->dot, LV_OPA_COVER, 0);
401	                }
402	                sb_show(s->dot);
403	                s->dot_last = want;
404	            }
405	        }
406	    }
407	}
