445	/** @brief 左簇：从 x0 往右打包；返回左簇末墨迹 x1。pos[] = 各图标墨迹 x0。 */
446	static int sb_left_layout(int x0, bool ble, bool hr, bool pwr, bool cad,
447	                          int pos[5])
448	{
449	    const bool on[5] = { true, ble, hr, pwr, cad };
450	    int x = x0;
451	    int end = x - 1;
452	
453	    for (int i = 0; i < 5; i++) {
454	        if (!on[i]) {
455	            pos[i] = -1;
456	            continue;
457	        }
458	        pos[i] = x;
459	        end = x + s_slot[i].ink_w - 1;
460	        x = end + 1 + SB_INK_GAP_ICON;
461	    }
462	    return end;
463	}
