465	/**
466	 * @brief 右簇：电量图标**墨迹右沿钉在 228**，从右往左打包（全部按墨迹间隙算）。
467	 *
468	 * pos[0]=REC 墨迹 x0、pos[1]=NAV、pos[2]=电量图标；-1 = 隐藏。
469	 * 电量不显示百分比，图标就是右簇最右一项。
470	 */
471	static int sb_right_layout(bool rec, bool nav, int pos[3])
472	{
473	    int x;
474	    int left;
475	
476	    pos[2] = SB_BATT_INK_RIGHT - s_slot[SB_BAT].ink_w + 1;
477	    left = pos[2];
478	    /* x = 紧邻左侧那一项的**右边界（不含）**；NAV 隐藏时 REC 直接用
479	     * “NAV→电量 8” 的间隙贴到电量左边（模拟器 right_layout 同一规则）。 */
480	    x = pos[2] - SB_INK_GAP_NAV_BAT;
481	    pos[1] = nav ? (x - s_slot[SB_NAV].ink_w) : -1;
482	    if (nav) {
483	        left = pos[1];
484	        x = pos[1] - SB_INK_GAP_REC_NAV;
485	    }
486	    pos[0] = rec ? (x - SB_REC_D) : -1;
487	    if (rec) {
488	        left = pos[0];
489	    }
490	    return left;
491	}
492	
493	static uint32_t sb_layout_make_key(int time_ink_w, bool ble,
494	                                   bool hr, bool pwr, bool cad, bool rec,
495	                                   bool nav)
496	{
497	    uint32_t key = (uint32_t)(time_ink_w & 0x3F);
498	
499	    key = key * 2u + (ble ? 1u : 0u);
500	    key = key * 2u + (hr ? 1u : 0u);
501	    key = key * 2u + (pwr ? 1u : 0u);
502	    key = key * 2u + (cad ? 1u : 0u);
503	    key = key * 2u + (rec ? 1u : 0u);
504	    key = key * 2u + (nav ? 1u : 0u);
505	    return key;
506	}
507	
508	/**
509	 * @brief 按墨迹规则排两簇；碰撞时按 踏频→功率→NAV→BLE 依次隐藏。
510	 *
511	 * @details 布局只依赖「时间宽度、六个可隐藏项是否在」——这些都没变的 1 s 拍
512	 *          直接跳过，不碰对象位置。右簇右端固定 228（电量图标墨迹右沿）。
513	 */
514	static void sb_layout(int time_ink_w, bool ble, bool hr,
515	                      bool pwr, bool cad, bool rec, bool nav)
516	{
517	    const uint32_t key = sb_layout_make_key(time_ink_w, ble, hr, pwr, cad,
518	                                            rec, nav);
519	    const int x0 = SB_TIME_X + time_ink_w + SB_INK_GAP_TIME;   /* 时间墨迹 x1+1+8 */
520	    int pos[5];
521	    int rpos[3];
522	    int left_end;
523	    int right_left;
524	
525	    if (s_has_layout && key == s_layout_key) {
526	        return;
527	    }
528	    s_layout_key = key;
529	    s_has_layout = true;
530	
531	    for (int guard = 0; guard < 5; guard++) {
532	        left_end = sb_left_layout(x0, ble, hr, pwr, cad, pos);
533	        right_left = sb_right_layout(rec, nav, rpos);
534	        if (right_left - left_end - 1 >= SB_MIN_BLANK) {
535	            break;
536	        }
537	        if (cad) {
538	            cad = false;
539	        } else if (pwr) {
540	            pwr = false;
541	        } else if (nav) {
542	            nav = false;
543	        } else if (ble) {
544	            ble = false;
545	        } else {
546	            break;
547	        }
548	    }
549	
550	    left_end = sb_left_layout(x0, ble, hr, pwr, cad, pos);
551	    right_left = sb_right_layout(rec, nav, rpos);
552	    (void)left_end;
553	    (void)right_left;
554	
555	    for (int i = 0; i < 5; i++) {
556	        s_ink_x[i] = pos[i];
557	        s_shown[i] = (pos[i] >= 0);
558	    }
559	    s_ink_x[SB_NAV] = rpos[1];
560	    s_shown[SB_NAV] = (rpos[1] >= 0);
561	    s_ink_x[SB_BAT] = rpos[2];
562	    s_shown[SB_BAT] = (rpos[2] >= 0);
563	    s_rec_x = rpos[0];
564	
565	    for (int k = 0; k < SB_SLOT_N; k++) {
566	        if (s_shown[k]) {
567	            sb_slot_place(k);
568	        }
569	    }
570	}
