572	/* ── 数据 → 语义色 ─────────────────────────────────────────────────── */
573	
574	static sb_tone_t sb_gps_tone(const bicycle_runtime_t * rt)
575	{
576	    bool alive = rt && rt->gnss_alive;
577	    bool valid = rt && rt->gnss_valid;
578	    uint8_t q = rt ? rt->gnss_fix_quality : 0;
579	    uint8_t sats = rt ? rt->gnss_satellites : 0;
580	    uint8_t hdop = rt ? rt->gnss_hdop_x10 : 0;
581	
582	    /* 旧：失联红 / 未定位白 / 弱黄闪 / 正常绿。新：红 / 浅灰 / 红 / 墨色。 */
583	    if (!alive) {
584	        return SB_TONE_RED;
585	    }
586	    if (!valid) {
587	        return SB_TONE_TRACK;
588	    }
589	    if (q <= 1 || sats < 5 || hdop > 20) {
590	        return SB_TONE_RED;
591	    }
592	    return SB_TONE_INK;
593	}
594	
595	static sb_tone_t sb_ble_tone(bool radio_on, bool connected)
596	{
597	    /* 左簇的五个图标**位置固定**：蓝牙关着也占位（浅灰），不整颗消失，
598	     * 否则其余图标会跟着左移，和环心/骑行页的对齐口径对不上。 */
599	    if (!radio_on) {
600	        return SB_TONE_TRACK;
601	    }
602	    /* 旧：诊断异常红闪 10 s。新：红色常亮（不再有动画）。 */
603	    if (myvendor_diag_ble_unhealthy_age_ms() < SB_BLE_ALERT_MS) {
604	        return SB_TONE_RED;
605	    }
606	    return connected ? SB_TONE_INK : SB_TONE_TRACK;
607	}
