609	/** @brief 传感器图标：**始终占位**；就绪墨色，未配对/未就绪浅灰。 */
610	static void sb_sensor_tones(sb_tone_t tone[SB_SLOT_N])
611	{
612	    static const uint8_t slot_of_kind[MYVENDOR_SYS_SENSOR_KIND_N] = {
613	        SB_HR, SB_CAD, SB_PWR,
614	    };
615	    myvendor_devctl_sensor_rec_t recs[MYVENDOR_DEVCTL_SENSOR_REC_MAX];
616	    myvendor_sys_sensor_ui_t ui;
617	    size_t n = 0;
618	    size_t i;
619	    uint8_t k;
620	    bool want[MYVENDOR_SYS_SENSOR_KIND_N];
621	    bool sensor_on = myvendor_devctl_sensor_get();
622	
623	    for (k = 0; k < MYVENDOR_SYS_SENSOR_KIND_N; k++) {
624	        want[k] = false;
625	    }
626	
627	    if (sensor_on &&
628	        myvendor_devctl_sensor_recs_get(recs, MYVENDOR_DEVCTL_SENSOR_REC_MAX,
629	                                        &n) == 0) {
630	        for (i = 0; i < n; i++) {
631	            if (recs[i].autorc && recs[i].kind < MYVENDOR_SYS_SENSOR_KIND_N) {
632	                want[recs[i].kind] = true;
633	            }
634	        }
635	    }
636	
637	    myvendor_sys_sensor_ui_get(&ui);
638	
639	    for (k = 0; k < MYVENDOR_SYS_SENSOR_KIND_N; k++) {
640	        const uint8_t slot = slot_of_kind[k];
641	        bool ready = (ui.slot[k].link == MYVENDOR_SYS_SENSOR_LINK_READY);
642	
643	        /* 关功能/未配对也画浅灰占位（设计口径：五个图标常驻，靠颜色区分）。 */
644	        tone[slot] = (sensor_on && want[k] && ready) ? SB_TONE_INK
645	                                                     : SB_TONE_TRACK;
646	    }
647	}
