663	static void sb_time_update(void)
664	{
665	    time_t now = time(NULL);
666	    int hour = -1;
667	    int min = -1;
668	
669	    if (now >= 1704067200) {
670	        if (!myvendor_devctl_tz_hms((long)now, &hour, &min)) {
671	            hour = -1;
672	            min = -1;
673	        }
674	    }
675	
676	    if (hour < 0) {
677	        myvendor_sys_gnss_t cfix;
678	        bool got = myvendor_sys_onboard_gnss_get(&cfix);
679	
680	        if (!got) {
681	            got = myvendor_sys_phone_gnss_get(&cfix);
682	        }
683	
684	        if (got && cfix.utc_sec >= 1704067200u) {
685	            time_t utc = (time_t)cfix.utc_sec;
686	            struct timeval tv;
687	
688	            tv.tv_sec = utc;
689	            tv.tv_usec = 0;
690	            (void)settimeofday(&tv, NULL);
691	            if (!myvendor_devctl_tz_hms((long)utc, &hour, &min)) {
692	                hour = -1;
693	                min = -1;
694	            }
695	        }
696	    }
697	
698	    if (hour < 0) {
699	        (void)bicycle_gpx_sim_get_wall_hms(&hour, &min);
700	    }
701	
702	    if (hour < 0) {
703	        hour = 0;
704	        min = 0;
705	    }
706	
707	    {
708	        const uint16_t hm = (uint16_t)(hour * 60 + min);
709	
710	        if (hm != s_last_time_hm) {
711	            sb_text_metrics_t m;
712	
713	            lv_snprintf(s_time_buf, sizeof(s_time_buf), "%02d:%02d", hour, min);
714	            lv_label_set_text(s_time, s_time_buf);
715	            sb_text_measure(s_time_buf, &m);
716	            /* 首字有 side bearing 时把 label 反向外移 ⇒ 墨迹恒定从 x=12 起。 */
717	            lv_obj_set_x(s_time, SB_TIME_X - m.ink_x0);
718	            s_time_ink_w = m.ink_w;
719	            s_last_time_hm = hm;
720	        }
721	    }
722	}
