729	    /* 电量只画图标（三档 + 低电红色），不显示百分比、不占文字宽度。 */
730	    if (glyph != s_batt_glyph) {
731	        hfi_set(s_slot[SB_BAT].ico, glyph);
732	        s_batt_glyph = glyph;
