736	static void status_bar_refresh(void)
737	{
738	    const bicycle_runtime_t * rt = bicycle_runtime_get();
739	    sb_tone_t tone[SB_SLOT_N];
740	    bool dot_on[SB_SLOT_N];
741	    bool ble;
742	    bool rec, nav, paused;
743	    int time_w;
744	
745	    if (s_time == NULL) {
746	        return;
747	    }
748	
749	    bicycle_status_bar_set_battery_pct(myvendor_sys_battery_percent());
750	
751	    sb_palette_apply(false);
752	    sb_time_update();
753	    sb_battery_update();
754	
755	    for (int k = 0; k < SB_SLOT_N; k++) {
756	        tone[k] = SB_TONE_HIDE;
757	        dot_on[k] = false;
758	    }
759	
760	    /* 左簇：GPS 恒在；BLE 关电台才隐藏；心率/功率/踏频看配对。 */
761	    tone[SB_GPS] = sb_gps_tone(rt);
762	    dot_on[SB_GPS] = rt && rt->gnss_valid;
763	
764	    ble = myvendor_devctl_radio_get();
765	    tone[SB_BLE] = sb_ble_tone(ble, myvendor_sys_phone_ble_connected());
766	    dot_on[SB_BLE] = myvendor_sys_phone_ble_connected();
767	
768	    sb_sensor_tones(tone);
769	
770	    /* REC：记录中红、暂停灰；未记录隐藏（旧 PAUSE 药丸并入 REC 颜色）。
771	     * R1-S4a：真实暂停路径（map_page_pause_ride）会把 runtime.recording 置 false
772	     * —— 那表示"计时暂停"，不是"没有骑行"。REC 的可见性必须同时看 paused，
773	     * 否则暂停后圆点直接消失，设计里"暂停 = 灰点"就永远走不到。 */
774	    paused = helm_shell_paused();
775	    rec = rt && (rt->recording || paused);
776	
777	    /* NAV：导航中蓝，未导航隐藏。 */
778	    nav = map_page_nav_active(live_map_page_instance());
779	    tone[SB_NAV] = nav ? SB_TONE_BLUE : SB_TONE_HIDE;
780	
781	    /* 电量：<20% 红；未知 = 浅灰；图标字形按 20/60 分级。 */
782	    if (s_battery_pct < 0) {
783	        tone[SB_BAT] = SB_TONE_TRACK;
784	    } else if (s_battery_pct < 20) {
785	        tone[SB_BAT] = SB_TONE_RED;
786	    } else {
787	        tone[SB_BAT] = SB_TONE_INK;
788	    }
789	
790	    /* 布局：先把本拍数据层的可见性取出来算两簇，再统一上色。 */
791	    time_w = s_time_ink_w;
792	
793	    sb_layout(time_w,
794	              tone[SB_BLE] != SB_TONE_HIDE,
795	              tone[SB_HR] != SB_TONE_HIDE,
796	              tone[SB_PWR] != SB_TONE_HIDE,
797	              tone[SB_CAD] != SB_TONE_HIDE,
798	              rec, nav);
799	
800	    for (int k = 0; k < SB_SLOT_N; k++) {
801	        sb_slot_apply(k, tone[k], s_shown[k], dot_on[k]);
802	    }
803	
804	    /* 电量只有图标：颜色在 sb_slot_apply 里按 tone 上（<20% 红）。 */
805	    sb_rec_apply(rec, paused);
806	}
