/* ── 共用状态栏（环形页 + 三个骑行页同一套；y=0..24，内容从 y≥24）──
 *
 * 两簇对齐（按**墨迹**而不是对象框）：
 *   左簇：时间 + GPS BLE 心率 功率 踏频，墨迹 x0=12，时间→GPS 8px，图标间 4px；
 *   右簇：REC + NAV + 电量，墨迹 x1=216，REC→NAV 4px，NAV→电量 8px，
 *         电量图标→文字 7px；NAV/REC 隐藏时整簇右移（间隙不变）；
 *   两簇之间弹性空白（space-between）。
 *
 * 图标是**原生 14px** 位图（helm_icons_14.c），不再把 20px 字形用
 * transform_scale 缩放（6× 下会糊成一团）。每个字形的墨迹宽/偏置集中在
 * 下面的 SB_INK[]，数值全部实测——改字形后必须重测：
 * docs/agent/evidence/WP-HELM9/R1/A/statusbar_coords.md（measure.py 生成）。
 */
#define SB_ICON_PX          14
#define SB_INK_GAP_TIME     8
#define SB_INK_GAP_ICON     4
#define SB_INK_GAP_REC_NAV  4
#define SB_INK_GAP_NAV_BAT  8
#define SB_INK_GAP_BAT_TXT  7
#define SB_REC_D            5      /* REC 实心点直径 */
#define SB_TIME_X           12
#define SB_BAT_TXT_X        193
#define SB_BAT_TXT_W        24
#define SB_MIN_BLANK        12

enum { SB_GPS, SB_BLE, SB_HR, SB_PWR, SB_CAD, SB_NAV, SB_BAT, SB_ICON_N };

/* 14px 字形墨迹：ink_w = 墨迹宽（BLE 含 3px 连接点）；
 * cx_off = 对象中心 − 墨迹左沿（补偿 side bearing）；
 * dot_dx = 连接点墨迹左沿 − 字形墨迹左沿（-1 = 不画点）。 */
typedef struct {
    helm_icon_t id;
    int ink_w;
    int cx_off;
    int dot_dx;
} sb_ink_t;

static const sb_ink_t SB_INK[SB_ICON_N] = {
    [SB_GPS] = { HELM_ICON_GPS,     14, 7, 11 },
    [SB_BLE] = { HELM_ICON_BLE,     13, 4, 10 },  /* 7 字形 + 3 + 3 点 */
    [SB_HR]  = { HELM_ICON_HR,      12, 6, -1 },
    [SB_PWR] = { HELM_ICON_POWER,    9, 5, -1 },
    [SB_CAD] = { HELM_ICON_CADENCE, 10, 5, -1 },
    [SB_NAV] = { HELM_ICON_NAV,     10, 5, -1 },
    [SB_BAT] = { HELM_ICON_BATTERY, 12, 6, -1 },
};

typedef struct {
    lv_obj_t *time_l;
    lv_obj_t *batt_l;
    lv_obj_t *batt_i;
    lv_obj_t *rec_dot;
    lv_obj_t *nav_i;
} statusbar_ui_t;

static statusbar_ui_t SB;

static void status_dot(lv_obj_t *p, int x, int y, int d, uint32_t col,
                       bool hollow)
{
    lv_obj_t *o = B(p, x, y, d, d, col,
                    hollow ? LV_OPA_TRANSP : LV_OPA_COVER, d / 2);

    if (hollow) {
        lv_obj_set_style_border_width(o, 1, 0);
        lv_obj_set_style_border_color(o, lv_color_hex(col), 0);
        lv_obj_set_style_border_opa(o, LV_OPA_COVER, 0);
    }
}

/** 原生 14px 图标：对象中心 = 墨迹左沿 + cx_off（表驱动，无缩放）。 */
static lv_obj_t *sb_icon(lv_obj_t *p, int k, int ink_x0, uint32_t col)
{
    const sb_ink_t *g = &SB_INK[k];

    return hfi_create_px(p, g->id, SB_ICON_PX, ink_x0 + g->cx_off, 12, col);
}

/** 按“墨迹左沿”放一个 14px 图标 + 可选连接点。 */
static void icon_at_ink(int k, int ink_x0, bool on)
{
    uint32_t col = on ? P_INK : P_TRACK;

    (void)sb_icon(s_scr, k, ink_x0, col);
    if (SB_INK[k].dot_dx >= 0) {
        status_dot(s_scr, ink_x0 + SB_INK[k].dot_dx, 16, 3, col, !on);
    }
}

/** 左簇墨迹布局：返回左簇最后一个墨迹 x1；pos[] 为各图标墨迹 x0（-1=隐藏）。 */
static int left_cluster_layout(int x0, bool ble, bool hr, bool pwr, bool cad,
                               int pos[5])
{
    const bool on[5] = { true, ble, hr, pwr, cad };
    int x = x0;
    int end = x - 1;

    for (int i = 0; i < 5; i++) {
        if (!on[i]) {
            pos[i] = -1;
            continue;
        }
        pos[i] = x;
        end = x + SB_INK[i].ink_w - 1;
        x = end + 1 + SB_INK_GAP_ICON;
    }
    return end;
}

/** 右簇：从电量文字墨迹左沿往左排（pos[] = REC/NAV/电量 的墨迹 x0，-1=隐藏）；
 *  返回右簇最左墨迹 x0。 */
static int right_cluster_layout(bool rec, bool nav, int txt_x0, int pos[3])
{
    int x = txt_x0 - SB_INK_GAP_BAT_TXT;   /* 电量图标的墨迹右侧（不含） */
    int left;

    pos[2] = x - SB_INK[SB_BAT].ink_w;
    left = pos[2];
    x = pos[2] - SB_INK_GAP_NAV_BAT;
    pos[1] = nav ? x - SB_INK[SB_NAV].ink_w : -1;
    if (nav) {
        left = pos[1];
        x = pos[1] - SB_INK_GAP_REC_NAV;
    }
    pos[0] = rec ? x - SB_REC_D : -1;
    if (rec) {
        left = pos[0];
    }
    return left;
}

/** 电量字形分级：<20% 空、20..59% 半、≥60% 满（三者墨迹包围盒相同，位置不跳）。 */
static helm_icon_t batt_glyph(void)
{
    if (s_batt < 20) {
        return HELM_ICON_BATT_EMPTY;
    }
    if (s_batt < 60) {
        return HELM_ICON_BATT_HALF;
    }
    return HELM_ICON_BATTERY;
}

static void statusbar_refresh(void)
{
    char buf[16];
    const bool low = s_batt < 20;
    const uint32_t bcol = low ? P_RED : P_INK;

    if (SB.time_l == NULL) {
        return;
    }
    snprintf(buf, sizeof(buf), "%d:%02d", (s_min / 60) % 24, s_min % 60);
    lv_label_set_text(SB.time_l, buf);

    snprintf(buf, sizeof(buf), "%d%%", s_batt);
    lv_label_set_text(SB.batt_l, buf);
    lv_obj_set_style_text_color(SB.batt_l, lv_color_hex(bcol), 0);
    lv_obj_set_style_text_color(SB.batt_i, lv_color_hex(bcol), 0);
    hfi_set(SB.batt_i, batt_glyph());

    /* REC：记录中红点；暂停变灰；未记录隐藏。 */
    if (SB.rec_dot != NULL) {
        if (R.active && R.rec) {
            lv_obj_remove_flag(SB.rec_dot, LV_OBJ_FLAG_HIDDEN);
            lv_obj_set_style_bg_color(SB.rec_dot,
                                      lv_color_hex(R.paused ? P_TRACK : P_RED),
                                      0);
        } else {
            lv_obj_add_flag(SB.rec_dot, LV_OBJ_FLAG_HIDDEN);
        }
    }
    /* NAV：导航中显示（深蓝），未导航隐藏。 */
    if (SB.nav_i != NULL) {
        if (s_nav_active) {
            lv_obj_remove_flag(SB.nav_i, LV_OBJ_FLAG_HIDDEN);
            lv_obj_set_style_text_color(SB.nav_i,
                                        lv_color_hex(C_DEEP[M_NAV]), 0);
        } else {
            lv_obj_add_flag(SB.nav_i, LV_OBJ_FLAG_HIDDEN);
        }
    }
}

/** 建状态栏（环形页与骑行三页共用）。 */
static void statusbar_build(void)
{
    char tbuf[16];
    int time_end;
    int pos[5];
    int rpos[3];
    bool show_ble = true;
    bool cluster_off = !s_sens_on[0] && !s_sens_on[1] && !s_sens_on[2];
    bool show_hr = !cluster_off;
    bool show_pwr = !cluster_off;
    bool show_cad = !cluster_off;
    bool show_nav = s_nav_active;
    bool show_rec = R.active && R.rec;
    int left_end;
    int right_left;
    int txt_x0;
    int x0;

    memset(&SB, 0, sizeof(SB));
    (void)B(s_scr, 0, 0, 240, 24, P_PAPER, LV_OPA_COVER, 0);
    HAIR(s_scr, 0, 23, 240);

    /* ① 时间：墨迹 x0=12（12px，贴左）。 */
    snprintf(tbuf, sizeof(tbuf), "%d:%02d", (s_min / 60) % 24, s_min % 60);
    SB.time_l = LW(s_scr, tbuf, 12, P_INK, SB_TIME_X, 4,
                   text_width(tbuf, 12) + 2, LV_TEXT_ALIGN_LEFT);
    time_end = SB_TIME_X + text_width(tbuf, 12) - 1;

    /* ② 电量文字（右对齐到墨迹 x1=216）先算：右簇从它往左排。 */
