    TOUR_ST_KEY,        /**< arg=1/2 短按 KEY1/KEY2；arg=11/12 长按（调试注入）。 */
    TOUR_ST_DUMP,       /**< helm_shell_demo_ring_dump()：几何/墨迹行（布局断言读）。 */
    TOUR_ST_DEMO_BANNER,/**< arg=0..7（helm_shell_demo_banner；R1-S3b 导航态取证）。 */
    TOUR_ST_MENU_KEY,   /**< arg=1/2 短按、11/12 长按（helm_menu_demo_key；R1-S4a）。 */
    TOUR_ST_MENU_DUMP,  /**< helm_menu_demo_key(0)：屏幕/选中行/开关态。 */
    TOUR_ST_PWR,        /**< arg=1 单击、2 双击、3 长按 2s、4 取消确认框（R1-S4b）。 */
    TOUR_ST_PWR_DUMP,   /**< helm_pwr_demo_dump()：确认框/键帽/休眠态。 */
    TOUR_ST_SAVE_DUMP,  /**< helm_shell_demo_save_dump()：保存两段卡文案+键帽几何。 */
    TOUR_ST_NAV_GPX,    /**< name=GPX 路径（空则用默认/SIM_CLIMB_GPX）：真跟线导航。 */
    TOUR_ST_CLIMB_DUMP, /**< helm_shell_demo_climb_dump()：海拔页布局/文案（R1-S9）。 */
    TOUR_ST_DEMO_ENV,   /**< arg=坡度×10：runtime 注入 grade / +12m 爬升（R1-S9）。 */
    TOUR_ST_WAIT,       /**< arg=真实毫秒等待（R1-S4b：让两趟 GPX 文件名跨秒）。 */
    TOUR_ST_DIAL_PAUSE, /**< arg=0/1：表盘暂停态（收起暂停条，R1-S10）。 */
    TOUR_ST_DIAL_DUMP,  /**< helm_shell_demo_dial_dump()：表盘布局/文案（R1-S10）。 */
    TOUR_ST_NAV_SPEED,  /**< arg=导航模拟时速×10（路线 sim，R1-S10）。 */
    TOUR_ST_RT_SENSORS, /**< arg=心率 bpm（踏频固定 92；每个巡页拍重放，R1-S10）。 */
    TOUR_ST_GNSS_SIM,   /**< arg=回放时速×10：GPX 回放驱动真实 fix（R1-S10）。 */
    TOUR_ST_SEED,       /**< 会话注入 12.3 km / 25:22（只为截图里四格有值）。 */
    TOUR_ST_DIAL_SNAP,  /**< name=文件名；arg=时速×10：改 runtime→刷新→dump→截图。 */
    TOUR_ST_DONE,       /**< 结束。 */
} tour_kind_t;

typedef struct {
    tour_kind_t kind;
    int arg;
    const char *name;
    /** R1-S10：第二个整数参数（DIAL_SNAP 的心率；0 = 不覆盖）。
     *  既有步骤的初始化式省掉它 ⇒ 自动为 0。 */
    int arg2;
} tour_step_t;

