/**
 * @brief 环形主页专用剧本（WP-HELM10/R1-S2 取证）。
 *
 * 用 `SIM_UI_TOUR_SCRIPT=ring ./lvgl_sim --scene ui --headless --ui-tour DIR`

static void tour_tick_cb(lv_timer_t *tmr)
{
    (void)tmr;

    if (!s_tour.started || s_tour.done || s_tour.failed) {
        return;
    }
    if (s_tour.step < 0 || s_tour.step >= s_step_count) {
        tour_finish();
        return;
    }

    const tour_step_t *st = &s_steps[s_tour.step];

    /* R1-S10：传感器桩每 10 ms 写回 128/84；本定时器后创建，故每拍重放
     * 指定值，确保 500 ms 刷新读到的是巡页要取证的值（板端无此路径）。 */
    if (s_tour_hr_bpm > 0) {
        bicycle_runtime_update_sensors((uint16_t)s_tour_hr_bpm, true,
                                       (uint16_t)s_tour_cad_rpm, true, 0, false);
    }

    switch (st->kind) {
        case TOUR_ST_BOOT:
            s_tour.boot_wait++;
            if (tour_boot_ready()) {
                tour_log("boot: splash finished, page=%s, waited %d ticks (%u ms virtual)",
                         tour_page_name((int)lvgl_page_current_id()),
                         s_tour.boot_wait, (unsigned)s_tour.boot_wait * TOUR_TIMER_MS);
                tour_next_step();
            } else if (s_tour.boot_wait >= TOUR_BOOT_TIMEOUT) {
                tour_log("boot: timeout after %d ticks, current page=%s (continue)",
                         s_tour.boot_wait,
                         tour_page_name((int)lvgl_page_current_id()));
                tour_next_step();
            }
            return;

        case TOUR_ST_OPEN: {
            bicycle_pm_id_t cur = lvgl_page_current_id();

            if ((int)cur == st->arg) {
                tour_log("open %s: already current, skip", tour_page_name(st->arg));
            } else {
                int rc = lv_pm_open_page_msg((lv_pm_id)st->arg, LV_PM_MSG_NONE);

                if (rc == 0) {
                    tour_log("open %s: ok", tour_page_name(st->arg));
                } else {
                    tour_log("open %s: FAILED rc=%d", tour_page_name(st->arg), rc);
                    s_tour.failed = true;
                    tour_finish();
                    return;
                }
            }
            tour_next_step();
            return;
        }

        case TOUR_ST_CLOSE: {
            bicycle_pm_id_t cur = lvgl_page_current_id();

            if ((int)cur != st->arg) {
                tour_log("close %s: not current (now %s), skip",
                         tour_page_name(st->arg), tour_page_name((int)cur));
            } else {
                int rc = lv_pm_close_page_msg(LV_PM_MSG_NONE);

                if (rc == 0) {
                    tour_log("close %s: ok", tour_page_name(st->arg));
                } else {
                    tour_log("close %s: FAILED rc=%d", tour_page_name(st->arg), rc);
                    s_tour.failed = true;
                    tour_finish();
                    return;
                }
            }
            tour_next_step();
            return;
        }

        case TOUR_ST_THEME:
            if (lvgl_page_theme_set_by_name(st->name)) {
                tour_log("theme -> %s (now %s)", st->name, lvgl_page_theme_name());
            } else {
                tour_log("theme -> %s: FAILED (now %s)", st->name,
                         lvgl_page_theme_name());
                s_tour.failed = true;
                tour_finish();
                return;
            }
            tour_next_step();
            return;

        case TOUR_ST_DEMO_PAGE:
            if (st->name != NULL && helm_shell_demo_page(st->name)) {
                tour_log("demo page -> %s (current=%s)", st->name,
                         tour_page_name((int)lvgl_page_current_id()));
            } else {
                tour_log("demo page -> %s: FAILED", st->name ? st->name : "(null)");
                s_tour.failed = true;
                tour_finish();
                return;
            }
            tour_next_step();
            return;

        case TOUR_ST_DEMO_RING:
            helm_shell_demo_ring(st->arg);
            tour_log("demo ring mode=%d", st->arg);
            tour_next_step();
            return;

        case TOUR_ST_DEMO_RING_STYLE:
            helm_shell_demo_ring_style(st->arg);
            tour_log("demo ring style=%d", st->arg);
            tour_next_step();
            return;

        case TOUR_ST_DEMO_RIDE:
            helm_shell_demo_ride((float)st->arg / 10.0f);
            tour_log("demo ride speed=%.1f", (double)st->arg / 10.0);
            tour_next_step();
            return;

        case TOUR_ST_DEMO_PAUSE:
            helm_shell_demo_pause(st->arg != 0);
            tour_log("demo pause=%d", st->arg);
            tour_next_step();
            return;

        case TOUR_ST_DEMO_BOTTOM:
            helm_shell_demo_bottom(st->arg);
            tour_log("demo bottom=%d", st->arg);
            tour_next_step();
            return;

        case TOUR_ST_DEMO_BANNER:
            helm_shell_demo_banner(st->arg);
            tour_log("demo banner=%d", st->arg);
            tour_next_step();
            return;

        case TOUR_ST_DUMP_RIDE:
            helm_shell_demo_ride_dump();
            tour_next_step();
            return;

        case TOUR_ST_KEY:
            /* arg: 1/2 = KEY1/KEY2 短按；11/12 = 长按。 */
            helm_shell_demo_key(st->arg % 10, st->arg >= 10);
            tour_log("key inject KEY%d %s", st->arg % 10,
                     st->arg >= 10 ? "long" : "short");
            tour_next_step();
            return;

        case TOUR_ST_MENU_KEY:
            /* arg: 1/2 = KEY1/KEY2 短按；11/12 = 长按；21 = KEY1 双击。 */
            tour_log("key inject menu KEY%d kind=%d radio=%d", st->arg % 10,
                     st->arg / 10, myvendor_devctl_radio_get() ? 1 : 0);
            helm_menu_demo_key(st->arg % 10, st->arg / 10);
            tour_next_step();
            return;

        case TOUR_ST_MENU_DUMP:
            helm_menu_demo_key(0, 0);
            tour_log("menu dump radio=%d",
                     myvendor_devctl_radio_get() ? 1 : 0);
            tour_next_step();
            return;

        case TOUR_ST_PWR:
            /* arg: 1=单击 2=双击 3=长按 2s 4=取消确认框（真 helm_pwr 状态机）。 */
            tour_log("pwr inject %d", st->arg);
            helm_pwr_demo_action(st->arg);
            tour_next_step();
            return;

        case TOUR_ST_PWR_DUMP:
            helm_pwr_demo_dump();
            tour_next_step();
            return;

        case TOUR_ST_SAVE_DUMP:
            helm_shell_demo_save_dump();
            tour_next_step();
            return;

        case TOUR_ST_NAV_GPX: {
            const char * path = (st->name != NULL && st->name[0] != '\0')
                ? st->name : getenv("SIM_CLIMB_GPX");
            map_page_t * page = lvgl_page_map();
            bool ok;

            if (path == NULL || path[0] == '\0') {
                path = SIM_CLIMB_GPX_DEFAULT;
            }
            ok = (page != NULL) && map_page_nav_from_gpx(page, path, false);
            tour_log("nav gpx %s -> %s", path, ok ? "ok" : "FAILED");
            if (!ok) {
                s_tour.failed = true;
                tour_finish();
                return;
            }
            tour_next_step();
            return;
        }

        case TOUR_ST_CLIMB_DUMP:
            tour_climb_dump();
            tour_next_step();
            return;

        case TOUR_ST_DEMO_ENV:
            /* 真 runtime 入口：录制中 update_env 才把 dalt 记进 gain。
             * 同一拍里立刻走一次 helm_shell_demo_page("climb") 的同步刷新 + dump：
             * 地图页的 gpx 定时器（200 ms）会用 env 把 grade 写回 0（模拟器没有
             * IMU），隔拍再读就看不到 3.4% 了。 */
            bicycle_runtime_set_recording(true);
            bicycle_runtime_update_env(500.0f, true,
                (float)st->arg / 10.0f, 12.0f);
            (void)helm_shell_demo_page("climb");
            tour_log("demo env grade=%.1f%% gain=12m alt=500m rec=1",
                     (double)st->arg / 10.0);
            tour_climb_dump();
            tour_next_step();
            return;

        case TOUR_ST_DIAL_PAUSE:
            helm_shell_demo_dial_pause(st->arg != 0);
            tour_log("dial pause=%d", st->arg);
            tour_next_step();
            return;

        case TOUR_ST_DIAL_DUMP:
            helm_shell_demo_dial_dump();
            tour_next_step();
            return;

        case TOUR_ST_NAV_SPEED:
            /* 路线 sim 的速度：配置 + 已在跑的 sim 同步改（R1-S10 取证用）。 */
            bicycle_config_set_nav_sim_speed_kph((float)st->arg / 10.0f);
            bicycle_route_sim_set_speed((float)st->arg / 10.0f);
            tour_log("nav sim speed=%.1f", (double)st->arg / 10.0);
            tour_next_step();
            return;

        case TOUR_ST_RT_SENSORS:
            s_tour_hr_bpm = st->arg;
            s_tour_cad_rpm = 92;
            bicycle_runtime_update_sensors((uint16_t)st->arg, true, 92, true,
                                           0, false);
            (void)helm_shell_refresh();
            tour_log("rt sensors hr=%d cad=92", st->arg);
            tour_next_step();
            return;

        case TOUR_ST_GNSS_SIM: {
            map_page_t *page = lvgl_page_map();
            const char *path = (st->name != NULL && st->name[0] != '\0')
                ? st->name : SIM_CLIMB_GPX_DEFAULT;
            int rc = map_page_gnss_sim(page, path, false,
                                       (float)st->arg / 10.0f, 0.0f);

            tour_log("gnss sim %s speed=%.1f -> %d", path,
                     (double)st->arg / 10.0, rc);
            if (rc != 0) {
                s_tour.failed = true;
                tour_finish();
                return;
            }
            tour_next_step();
            return;
        }

        case TOUR_ST_SEED:
            bicycle_runtime_seed_session(12300.0, 1522000ull);
            (void)helm_shell_refresh();
            tour_log("seed 12.3km / 25:22");
            tour_next_step();
            return;

        case TOUR_ST_DIAL_SNAP: {
            /* 同一拍里：改 runtime → 刷新 → dump → 整屏截图。避免 500 ms
             * 定时器在中间把心率换回板级桩的 128（R1-S10 取证专用）。
             * arg2 = 心率（0 则不覆盖，保留桩的 128）。 */
            bicycle_runtime_t *drt =
                (bicycle_runtime_t *)(uintptr_t)bicycle_runtime_get();

            if (drt != NULL) {
                drt->speed_kph = (float)st->arg / 10.0f;
                if (st->arg2 > 0) {
                    drt->hr_bpm = (uint16_t)st->arg2;
                    drt->hr_valid = true;
                    drt->hr_avg_bpm = (uint16_t)(st->arg2 - 3);
                    drt->hr_max_bpm = (uint16_t)(st->arg2 + 2);
                    drt->cadence_rpm = 92;
                    drt->cadence_valid = true;
                    s_tour_hr_bpm = st->arg2;
                    s_tour_cad_rpm = 92;
                }
            }
            (void)helm_shell_refresh();
            helm_shell_demo_dial_dump();
            if (st->name != NULL) {
                tour_take_shot(st->name);
            }
            tour_log("dial snap speed=%.1f hr=%d", (double)st->arg / 10.0,
                     st->arg2);
            tour_next_step();
            return;
        }

        case TOUR_ST_WAIT:
            if (st->arg > 0) {
                usleep((useconds_t)st->arg * 1000u);
            }
            tour_log("wait %d ms (real)", st->arg);
            tour_next_step();
            return;

        case TOUR_ST_DUMP:
            helm_shell_demo_ring_dump();
            tour_next_step();
            return;

        case TOUR_ST_SETTLE: {
            /* arg > 0：本步固定帧数；arg < 0：上限（不超过 --tour-frames）。 */
            int frames = s_tour.frames;

            if (st->arg > 0) {
                frames = st->arg;
            } else if (st->arg < 0 && frames > -st->arg) {
                frames = -st->arg;
            }

            /* 转场动画没完先等它；卡死就 drain（与板端抢占策略一致）。 */
            if (lv_pm_nav_busy()) {
                s_tour.nav_wait++;
                if (s_tour.nav_wait >= TOUR_NAV_TIMEOUT) {
                    tour_log("settle: nav busy %d ticks, drain", s_tour.nav_wait);
                    lv_pm_nav_drain();
                    s_tour.nav_wait = 0;
                    s_tour.waited = 0;
                }
                return;
            }

            if (s_tour.waited < frames) {
                s_tour.waited++;
                return;
            }
            tour_next_step();
            return;
        }

        case TOUR_ST_SHOT:
            tour_take_shot(st->name);
            tour_next_step();
            return;

        case TOUR_ST_MTP:
            sim_ui_mtp_force_attached = (st->arg != 0);
            tour_log("mtp stub: %s", sim_ui_mtp_force_attached ? "host attached" : "host off");
            tour_next_step();
            return;

        case TOUR_ST_DONE:
        default:
            tour_finish();
            return;
    }
}

