static int write_ppm(const char * dir, const char * name)
{
    char path[512];
    FILE * f;
    const uint16_t * px = (const uint16_t *)g_fb;
    uint8_t row[240 * 3];

    snprintf(path, sizeof(path), "%s/probe_%s.ppm", dir, name);
    f = fopen(path, "wb");
    if (f == NULL) {
        perror(path);
        return -1;
    }
    fprintf(f, "P6\n240 320\n255\n");
    for (int y = 0; y < 320; y++) {
        for (int x = 0; x < 240; x++) {
            const uint16_t v = px[y * 240 + x];
            const uint8_t r = (uint8_t)((v >> 11) & 0x1F);
            const uint8_t g = (uint8_t)((v >> 5) & 0x3F);
            const uint8_t b = (uint8_t)(v & 0x1F);

            row[x * 3 + 0] = (uint8_t)((r * 255u + 15u) / 31u);
            row[x * 3 + 1] = (uint8_t)((g * 255u + 31u) / 63u);
            row[x * 3 + 2] = (uint8_t)((b * 255u + 15u) / 31u);
        }
        fwrite(row, 1, sizeof(row), f);
    }
    fclose(f);
    printf("probe: %s\n", path);
    return 0;
}

int main(int argc, char ** argv)
{
    const char * dir = (argc > 1) ? argv[1] : ".";
    lv_obj_t * scr;

    lv_init();

    g_disp = lv_display_create(240, 320);
    lv_display_set_color_format(g_disp, LV_COLOR_FORMAT_RGB565);
    lv_display_set_buffers(g_disp, g_fb, NULL, sizeof(g_fb),
                           LV_DISPLAY_RENDER_MODE_DIRECT);
    lv_display_set_flush_cb(g_disp, flush_cb);

    scr = lv_display_get_screen_active(g_disp);
    lv_obj_set_style_bg_color(scr, lv_color_black(), 0);
    lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);

    g_cont = lv_obj_create(scr);
    lv_obj_remove_style_all(g_cont);
    lv_obj_set_pos(g_cont, 0, 0);
    lv_obj_set_size(g_cont, 240, 24);

    memset(&g_state, 0, sizeof(g_state));
    bicycle_status_bar_init();

    for (size_t i = 0; i < sizeof(k_states) / sizeof(k_states[0]); i++) {
        g_state = k_states[i];
        bicycle_status_bar_refresh();
        lv_obj_invalidate(scr);
        lv_refr_now(g_disp);
        if (write_ppm(dir, g_state.name) != 0) {
            return 1;
        }
    }

    return 0;
}
