#!/usr/bin/env python3
"""编译 statusbar_probe（取证探针）。

复用模拟器 build/compile_commands.json 里 bicycle_status_bar.c 的编译参数
（同一份 LVGL / 同一套板端 include / 同一个 sim_prelude.h），只把源文件换成
“探针 + 板端原版 bicycle_status_bar.c + helm_icons + 字体”。

用法:  python3 build_probe.py        # 输出 ../statusbar_probe
"""

import json
import os
import shlex
import subprocess
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
EVID = os.path.dirname(HERE)
SIM = "/home/jinsc/SDK/vela/lvgl_sim"
SIM_BUILD = os.path.join(SIM, "build")
CC_JSON = os.path.join(SIM_BUILD, "compile_commands.json")

UI = ("/home/jinsc/SDK/vela/openvela/vendor/my_vendor/boards/sf32lb52/"
      "my_vendor/ui/bicycle/src")

OUT = os.path.join(EVID, "statusbar_probe")


def flags_for_status_bar():
    entries = json.load(open(CC_JSON))
    for e in entries:
        if e["file"].endswith("/bicycle_status_bar.c"):
            argv = shlex.split(e["command"])
            break
    else:
        raise SystemExit("compile_commands.json 里找不到 bicycle_status_bar.c")

    out = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "-o":
            i += 2
            continue
        if a == "-c":
            i += 1
            continue
        if a.endswith("bicycle_status_bar.c"):
            i += 1
            continue
        out.append(a)
        i += 1
    return out


def main():
    args = flags_for_status_bar()

    srcs = [
        os.path.join(HERE, "statusbar_probe.c"),
        os.path.join(UI, "bicycle_status_bar.c"),
        os.path.join(UI, "lvgl_page", "helm_icons.c"),
        os.path.join(UI, "lvgl_page", "fonts", "helm_icons_14.c"),
        os.path.join(UI, "lvgl_page", "fonts", "helm_icons_20.c"),
        os.path.join(UI, "lvgl_page", "fonts", "helm_icons_26.c"),
        os.path.join(UI, "lvgl_page", "fonts", "helm_ui_12.c"),
        os.path.join(SIM_BUILD, "liblvgl.a"),
    ]
    libs = ["-lfreetype", "-lpng", "-lX11", "-lz", "-lm", "-lpthread"]

    # 参数列表 + 字面量 argv[0] + shell=False：不经过 shell，路径/宏里即使有
    # 空格或分号也不会被解释；编译器固定为 /usr/bin/cc（与 compile_commands 一致）。
    rest = args[1:] + srcs + libs + ["-o", OUT]
    print(shlex.join(["/usr/bin/cc"] + rest))
    rc = subprocess.call(["/usr/bin/cc"] + rest, shell=False)
    if rc != 0:
        return rc
    print("built:", OUT)
    return 0


if __name__ == "__main__":
    sys.exit(main())

